<script>
import * as axios from '@/handler/prehand';
const classOptions = ['一（1）班', '一（2）班', '一（3）班', '一（4）班', '一（5）班', '一（6）班', '一（7）班', '一（8）班', '一（9）班'];

const options = {
  data() {
    return {
      timeZone:'早读',//巡查类型
      value1: true,//开关按钮
      checkboxClassGroup1: [],//默认选择班级复选框
      autocompleteTeacherGroup:[],
      teacherClassBind:{},
      classes: classOptions,//用于遍历班级列表
      classname: '',//用于存储遍历出来的classname临时参数
      restaurants: [],
      teacherList: [],
      states: {},
      timeout: null,
      dialogImageUrl: '',//上传照片
      dialogVisible: false,//上传照片的提醒框
      fileList: [],//调用摄像头的照片列表
      grade1: '一年级',//用于标识年级
      feedbacksentence: '',//用户展示回显的数据
      //日期的数据
      pickerOptions: {
        disabledDate(time) {
          return time.getTime() > Date.now();
        },
        shortcuts: [{
          text: '今天',
          onClick(picker) {
            picker.$emit('pick', new Date());
          }
        }, {
          text: '昨天',
          onClick(picker) {
            const date = new Date();
            date.setTime(date.getTime() - 3600 * 1000 * 24);
            picker.$emit('pick', date);
          }
        }, {
          text: '一周前',
          onClick(picker) {
            const date = new Date();
            date.setTime(date.getTime() - 3600 * 1000 * 24 * 7);
            picker.$emit('pick', date);
          }
        }]
      },
      checkdate: new Date(Date.now()),
      images:[],//用于存储url

      isPreviewModalVisible: false,
      previewImageUrl: '',
    }
  },

  //处理远程检索教师姓名的文本框
  methods: {
    loadandquery(){
      this.uploaddata().then(()=>{
        this.querydata();
      });
    },
    // 在这里将classname传递到data中，方便autocomplete组件使用
    handleFocus(classname) {
      this.classname = classname;
    },
    handleinput(){
      if(this.states[this.classname]===''){
        console.log("内容被删除了")
        this.teacherClassBind[this.classname] = '';
      }
    },

    //清空的插槽
    clearInput(classname) {
      this.states[classname] = ''; // 清空对应 classname 的输入框内容
      this.teacherClassBind[classname]='';
      console.log(this.checkboxClassGroup1)
    },

    uploaddata() {
      console.log(this.checkboxClassGroup1);

      const url = '/tpi/adddata'; // 替换为你的目标URL
      const teacherNamesList = [];
      if (this.checkboxClassGroup1 != null) {
        for (const i of this.checkboxClassGroup1) {
          if (this.teacherClassBind[i]) {
            teacherNamesList.push(this.teacherClassBind[i])
          }
          else { teacherNamesList.push(this.states[i]) }
        }
      }
      const moment = require('moment');
      //还需要加上记录人。，从localstorage中找，登录的时候存一份，每次登录都覆盖
      const data = {
        classNames: this.checkboxClassGroup1, // 这是我们要发送的列表
        teacherNames: teacherNamesList,
        checkdate: moment(this.checkdate).format('YYYY-MM-DD'),
        censor: localStorage.getItem("username"),
        timeZone : this.timeZone
      };

      // 使用axios发起POST请求
      return axios.post(url, data)
        .then((response) => {
          this.feedbacksentence = response.data.data;
        })
        .catch(function (error) {
          console.error('请求出错：', error);
        });
    },

    querydata(){
      const moment = require('moment');
      axios.get('/tpi/querydata',{checkdate:moment(this.checkdate).format('YYYY-MM-DD')})
      .then(response=>{
        this.feedbacksentence = response.data.data
      })
      .catch(function (error) {
        console.error('请求出错：', error);
      })

      //查询url的链接列表
      axios.get('api/queryimage',{checkdate:moment(this.checkdate).format('YYYY-MM-DD')})
      .then(res=>{
        this.images = res.data.data
        console.log(this.images)
      })
      .catch(function (error) {
          console.error('请求出错：', error);
        })
    },


    handlePreview(image) {
      console.log('Preview image', image);
      this.previewImageUrl = image;
      this.isPreviewModalVisible = true;
      // 预览图片逻辑
    },
    handleDownload(image) {
      // 创建一个<a>元素
      const link = document.createElement('a');
      // 设置下载的文件名，这里我们从URL中提取文件名
      // 注意：这种方法假设URL以文件名结束，如果URL结构不同，你可能需要调整它
      const filename = image.substring(image.lastIndexOf('/') + 1);

      // 设置<a>元素的href为图片的URL
      link.href = image;
      // 设置download属性为希望保存的文件名
      link.download = filename || 'download';

      // 模拟点击<a>元素
      document.body.appendChild(link);
      link.click();
      // 移除<a>元素
      document.body.removeChild(link);
    },
    handleRemove(index) {
      this.images.splice(index, 1); // 从列表中删除图片
    },

    //用于加载每个班级对应的教师信息，根据年级参数查询后台
    loadteacher() {
      return axios.get('/tpi/loadteacher', { grade1: this.grade1 })
        .then(response => {
          return response.data.data;
        }
        ).catch(error => { this.$message.error('获取教师数据失败：' + error.message) })
    },

    autoloaddata(){
      const moment = require('moment');
      return axios.get('/tpi/loaddata',{grade1:this.grade1,timeZone:this.timeZone, checkdate:moment(this.checkdate).format('YYYY-MM-DD')})
      .then(response =>{
        return response.data.data;
      }).catch(error => { this.$message.error('自动加载数据失败：' + error.message) })
    },

    //autocomplete组件的操作
    querySearch(queryString, cb) {
      console.log(this.teacherList);
      var teacherList = this.teacherList[this.classname];
      var results = queryString ? teacherList.filter(this.createFilter(queryString)) : teacherList;
      // 调用 callback 返回建议列表的数据
      cb(results);
    },
    createFilter(queryString) {
      return (teacherList) => {
        return (teacherList.value.toLowerCase().indexOf(queryString.toLowerCase()) > -1);
      };
    },

    handleSelect(item) {
      if(this.checkboxClassGroup1.includes(this.classname)){
        this.teacherClassBind[this.classname] = item.value;
        console.log("AAAAAA");
        console.log(this.checkboxClassGroup1);
      }else{
        this.checkboxClassGroup1.push(this.classname);
        this.teacherClassBind[this.classname] = item.value;
        console.log("BBB");
        console.log(this.checkboxClassGroup1);
      }

      // console.log(this.teacherClassBind)
    }
  },

  mounted() {
    //只有返回的是promis对象，才能在链式调用中使用下一个then
    this.loadteacher()
      .then(teacherList => {
        this.teacherList = teacherList;
        // 初始化 states对象
        this.classes.forEach(classname => {
          this.$set(this.states, classname, '');
        });

        //自动查询数据库加载数据
        this.autoloaddata().then(response => {
          this.checkboxClassGroup1 = response["classnamelist"];
          if (response["classnamelist"] != null) {
            for (let i = 0; i < this.checkboxClassGroup1.length; i++) {
              this.states[this.checkboxClassGroup1[i]] = response["teachernamelist"][i];
              this.teacherClassBind[this.checkboxClassGroup1[i]] = response["teachernamelist"][i];
            }
            console.log(this.states);
          }
        }).catch(
          error => { this.$message.error('自动加载数据失败：' + error.message) }
        );
      })
      .catch(error => {
        console.error('Failed to load teacher list:', error);
        // 在这里处理加载教师数据失败的情况，例如显示错误信息
      });

  },

  //路由跳转的导航守卫
  beforeRouteLeave(to, from, next) {
      // 执行你的逻辑
      console.log('Leaving the route...');
      this.uploaddata();
      // 调用 next() 表示继续执行导航，如果要取消导航，可以调用 next(false)
      next();
    }
}




export default options;
</script>